if(!$title||!$course||!$unit||!$type||!$file)$error='Please complete all required fields and choose a file.';elseif($isPaid && $price <= 0)$error='Set a valid price for paid resources.';elseif($file['error']!==UPLOAD_ERR_OK)$error='The file upload failed. Please try again.';elseif($file['size']>10*1024*1024)$error='Maximum file size is 10 MB.';else{$allowed=['pdf','doc','docx','ppt','pptx','txt','jpg','jpeg','png'];$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if(!in_array($ext,$allowed,true))$error='Unsupported file type.';else{$dir=__DIR__.'/uploads/resources';if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(16)).'.'.$ext;$rel='uploads/resources/'.$name;if(move_uploaded_file($file['tmp_name'],$dir.'/'.$name)){$s=mysqli_prepare($connect,"INSERT INTO resources(uploader_id,title,course,course_unit,subject,topic,resource_type,description,file_path,is_paid,price,currency) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");$uid=(int)$_SESSION['user_id'];mysqli_stmt_bind_param($s,'issssssssids',$uid,$title,$course,$unit,$unit,$topic,$type,$desc,$rel,$isPaid,$price,$currency);if(mysqli_stmt_execute($s)){header('Location: dashboard.php');exit;}@unlink($dir.'/'.$name);}$error='Could not save the resource.';}}}
